// NewOpenRequestBody builds the HTTP request body from the payload of the
// "open" endpoint of the "boards" service.
func NewOpenRequestBody(p *boards.OpenPayload) *OpenRequestBody {
	body := &OpenRequestBody{
		NoteID: p.NoteID,
		Title:  p.Title,
	}
	return body
}

// NewSaveRequestBody builds the HTTP request body from the payload of the
// "save" endpoint of the "boards" service.
func NewSaveRequestBody(p *boards.SavePayload) *SaveRequestBody {
	body := &SaveRequestBody{
		Title: p.Title,
	}
	return body
}

// NewAddStickyRequestBody builds the HTTP request body from the payload of the
// "add_sticky" endpoint of the "boards" service.
func NewAddStickyRequestBody(p *boards.AddStickyPayload) *AddStickyRequestBody {
	body := &AddStickyRequestBody{
		Parent: p.Parent,
		Kind:   p.Kind,
		Text:   p.Text,
	}
	if p.Anchor != nil {
		body.Anchor = marshalBoardsBoardAnchorToBoardAnchorRequestBody(p.Anchor)
	}
	return body
}

// NewSaveStickyRequestBody builds the HTTP request body from the payload of
// the "save_sticky" endpoint of the "boards" service.
func NewSaveStickyRequestBody(p *boards.SaveStickyPayload) *SaveStickyRequestBody {
	body := &SaveStickyRequestBody{
		Text: p.Text,
	}
	return body
}

